interface QuantityChangedDetail {
  variantId: string;
  quantity: number;
}

interface CartElement extends HTMLElement {
  changeItemQuantity: (variantId: string, quantity: number) => void;
}

import { refreshMiniCart } from "./minicart-sync";
import "./minicart-body";

document.addEventListener("quantityChanged", (event) => {
  const { variantId, quantity } = (event as CustomEvent<QuantityChangedDetail>)
    .detail;
  (document.querySelector("uwp-cart") as CartElement)?.changeItemQuantity(
    variantId,
    quantity,
  );
});

// Reload cart page and refresh minicart on cartUpdated
document.addEventListener("cartUpdated", () => {
  refreshMiniCart();
  if (document.body.classList.contains("template-cart"))
    window.location.reload();
});

// Toggle minicart drawer when header cart icon is clicked
document.addEventListener("click", (event) => {
  const anchor = (event.target as HTMLElement).closest(
    ".header__action--cart > a",
  ) as HTMLAnchorElement | null;
  if (!anchor) return;

  event.preventDefault();

  const minicart = document.querySelector("uwp-minicart");
  if (minicart) {
    minicart.setAttribute("open", "true");
    refreshMiniCart();
  }
});

